      brute: ['test every substring: O(n³)', "function countSubstrings(s) {\n  let n = 0;\n  for (let i = 0; i < s.length; i++) for (let j = i; j < s.length; j++) {\n    const t = s.slice(i, j + 1);\n    if (t === [...t].reverse().join('')) n++;\n  }\n  return n;\n}"],
